package com.hms.services;
import com.hms.departments.*; import com.hms.doctors.*; import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/services") public class ServiceController {private final TenantRepository tenants;private final DepartmentRepository departments;private final HospitalServiceRepository services;private final DoctorRepository doctors;private final DoctorServiceLinkRepository links;public ServiceController(TenantRepository t,DepartmentRepository d,HospitalServiceRepository s,DoctorRepository dr,DoctorServiceLinkRepository l){tenants=t;departments=d;services=s;doctors=dr;links=l;} @GetMapping public List<HospitalService> list(@PathVariable String tenantSlug){return services.findAllByTenantIdOrderByNameAsc(tenant(tenantSlug));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public HospitalService create(@PathVariable String tenantSlug,@Valid @RequestBody CreateServiceRequest r){UUID t=tenant(tenantSlug);if(r.departmentId()!=null){Department d=departments.findById(r.departmentId()).orElseThrow(()->new IllegalArgumentException("Department not found"));if(!d.getTenantId().equals(t))throw new IllegalArgumentException("Department does not belong to hospital");}return services.save(new HospitalService(t,r));} @PostMapping("/doctors/{doctorId}") public List<UUID> assign(@PathVariable String tenantSlug,@PathVariable UUID doctorId,@Valid @RequestBody AssignServicesRequest r){UUID t=tenant(tenantSlug);Doctor doctor=doctors.findById(doctorId).orElseThrow(()->new IllegalArgumentException("Doctor not found"));if(!doctor.getTenantId().equals(t))throw new IllegalArgumentException("Doctor does not belong to hospital");List<HospitalService> valid=services.findAllById(r.serviceIds()).stream().filter(s->s.getTenantId().equals(t)).toList();if(valid.size()!=r.serviceIds().size())throw new IllegalArgumentException("Services do not belong to hospital");valid.forEach(s->links.save(new DoctorServiceLink(doctorId,s.getId())));return valid.stream().map(HospitalService::getId).toList();} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));}}
